SELECT NAME, VALUE FROM V$SYSSTAT
WHERE NAME LIKE '%physical reads%' OR NAME LIKE '%consistent gets%' OR NAME LIKE '%db block gets%';
-- 命中率估算：1 - physical reads / (consistent gets + db block gets)，分母为 0 时结果为 NULL。

-- 1. 先确认表上次分析时间（只读）：
SELECT OWNER, TABLE_NAME, NUM_ROWS, LAST_ANALYZED FROM DBA_TABLES
WHERE OWNER = '<SCHEMA>' AND TABLE_NAME = '<TABLE>';
-- 2. 确认后在非高峰执行（谨慎）：
-- DANGER: EXEC DBMS_STATS.GATHER_TABLE_STATS('<SCHEMA>', '<TABLE>');

SELECT * FROM (
  SELECT SQL_TEXT, ELAPSED_TIME, EXECUTIONS
  FROM V$SQL
  WHERE ELAPSED_TIME > 0
  ORDER BY ELAPSED_TIME DESC
) WHERE ROWNUM <= 20;

-- 1. 先确认（只读查询）：
SELECT SID, SERIAL#, USERNAME, STATUS, MACHINE FROM V$SESSION WHERE SID = <SID>;
-- 2. 确认无误后再执行（危险）：
-- DANGER: ALTER SYSTEM KILL SESSION '<SID>,<SERIAL#>';

SELECT * FROM (
  SELECT OWNER, SEGMENT_NAME, SEGMENT_TYPE, ROUND(BYTES/1024/1024, 2) AS SIZE_MB
  FROM DBA_SEGMENTS
  ORDER BY BYTES DESC
) WHERE ROWNUM <= 20;

SELECT DATABASE_NAME, LOG_MODE, OPEN_MODE FROM V$DATABASE;
SELECT * FROM (
  SELECT SEQUENCE#, FIRST_TIME, ARCHIVED
  FROM V$ARCHIVED_LOG
  WHERE FIRST_TIME > SYSDATE - 1
  ORDER BY FIRST_TIME DESC
) WHERE ROWNUM <= 20;
